<template><section class="wiki-recipes"><div class="catalog-toolbar"><input v-model="search" type="search" :placeholder="en?'Result / ingredient / recipe ID':'产物、材料名称或配方 ID'" @input="page=1"><select v-model="selected" @change="page=1"><option value="all">{{en?'All workstations':'全部工作台'}}</option><option v-for="t in types" :key="t" :value="t">{{recipeNames[lc][t]||t}}</option></select></div><p class="catalog-count">{{filtered.length}} {{en?'recipes':'条配方'}} · {{en?'Ingredient counts, component variants and accepted tags are retained.':'保留材料数量、物品组件和可替代材料标签。'}}</p><RecipeDisplay v-for="r in shown" :key="r.key" :recipe="r"/><nav class="catalog-pagination"><button :disabled="page===1" @click="page--">{{en?'Previous':'上一页'}}</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">{{en?'Next':'下一页'}}</button></nav></section></template>
<script setup lang="ts">
import{ref,computed,onMounted,watch}from'vue';import{useData}from'vitepress';import{getData,recipeNames,nameOf,locale}from'../lib/wiki';import RecipeDisplay from'./RecipeDisplay.vue';const props=withDefaults(defineProps<{type?:string}>(),{type:'all'});const{lang}=useData();const lc=computed(()=>locale(lang.value)),en=computed(()=>lc.value==='en');const all=ref<any[]>([]),catalog=ref<any>(),search=ref(''),selected=ref(props.type),page=ref(1);const types=computed(()=>[...new Set(all.value.map(r=>r.type))].sort());
function names(input:any):string{if(!input)return'';if(input.id)return input.id+' '+nameOf(catalog.value?.items[input.id],lang.value);if(input.tag)return input.tag+' '+(catalog.value?.tags[input.tag]??[]).map((id:string)=>nameOf(catalog.value?.items[id],lang.value)).join(' ');return(input.alternatives??[]).map(names).join(' ')}
const filtered=computed(()=>{const q=search.value.toLocaleLowerCase().trim();return all.value.filter(r=>(selected.value==='all'||r.type===selected.value)&&(!q||[r.id,names(r.output),...r.inputs.map(names)].join(' ').toLocaleLowerCase().includes(q)))});const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12))),shown=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12));watch(pages,()=>page.value=Math.min(page.value,pages.value));onMounted(async()=>{const[r,c]=await Promise.all([getData('recipes'),getData()]);all.value=Object.values(r);catalog.value=c;});
</script>
